[
  {
    "name": "browser_create",
    "description": "Create one shared, temporary, or named persistent Browser Profile, Browser Workspace, browser instance, and tab. Omit profile to use the Browser settings default (shared unless that page changes it).",
    "parameters": {
      "type": "object",
      "properties": {
        "profile": {
          "type": "string",
          "description": "Omit or shared reuses one identity across Sessions. persistent restores a named isolated Profile. temporary discards identity.",
          "enum": [
            "temporary",
            "persistent",
            "shared"
          ]
        },
        "name": {
          "type": "string",
          "description": "Named persistent Browser Profile. Required when profile is persistent."
        },
        "attach": {
          "type": "object",
          "description": "Attach a new instance or tab to an existing Session-owned hierarchy.",
          "additionalProperties": false,
          "properties": {
            "kind": {
              "type": "string",
              "description": "workspace starts another instance; browser starts another tab.",
              "enum": [
                "workspace",
                "browser"
              ]
            },
            "workspaceId": {
              "type": "string",
              "description": "Existing Browser Workspace to reuse."
            },
            "browserId": {
              "type": "string",
              "description": "Existing browser instance to reuse when kind is browser."
            }
          }
        }
      }
    }
  },
  {
    "name": "browser_focus",
    "description": "Focus one browser tab using its latest revision.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        },
        "expectedRevision": {
          "type": "integer",
          "description": "Latest revision returned by a browser operation."
        }
      },
      "required": [
        "target",
        "expectedRevision"
      ]
    }
  },
  {
    "name": "browser_screenshot",
    "description": "Capture the deterministic PNG screenshot facts for one browser tab.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        }
      },
      "required": [
        "target"
      ]
    }
  },
  {
    "name": "browser_navigate",
    "description": "Navigate one browser tab to a URL using its latest revision.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        },
        "expectedRevision": {
          "type": "integer",
          "description": "Latest revision returned by a browser operation."
        },
        "url": {
          "type": "string",
          "description": "URL to open in the browser tab."
        }
      },
      "required": [
        "target",
        "expectedRevision",
        "url"
      ]
    }
  },
  {
    "name": "browser_observe",
    "description": "Observe the latest facts for one browser tab, including a closed receipt.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        }
      },
      "required": [
        "target"
      ]
    }
  },
  {
    "name": "browser_input",
    "description": "Send synthetic Agent input to a browser tab using its latest revision.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        },
        "expectedRevision": {
          "type": "integer",
          "description": "Latest revision returned by a browser operation."
        },
        "url": {
          "type": "string",
          "description": "Optional URL for the synthetic input."
        },
        "text": {
          "type": "string",
          "description": "Optional text for the synthetic input."
        }
      },
      "required": [
        "target",
        "expectedRevision"
      ]
    }
  },
  {
    "name": "browser_close",
    "description": "Close one browser tab using the latest revision. Temporary Profiles discard identity; named Profiles keep the persist partition.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        },
        "expectedRevision": {
          "type": "integer",
          "description": "Latest revision returned by a browser operation."
        }
      },
      "required": [
        "target",
        "expectedRevision"
      ]
    }
  }
]
